400:               <td style="padding:6px 10px; border-bottom:1px solid #eee; color:#c62828">
401:                 ${error.Error}
402:               </td>
403:             </tr>`;
404:       });
405: 
406:       mensaje += `</tbody></table>`;
407:     }
408: 
409:     this.modalService.mostrarModal(mensaje, icono, titulo);
410:   }
